$(function() {
    if ((window.location.hostname !== "localhost") && (window.location.hostname !== "127.0.0.1")) {
        document.title = document.title+" : "+window.location.hostname;
    }
    // Send ready message to parent window
    if (window.opener) {
        localStorage.clear();
        // Send ready message to opener window
        window.opener.postMessage({ type: 'ready' }, '*');
        
        // Listen for messages from opener window
        window.addEventListener('message', function(event) {
            // console.log(event.data.token);
            
            // Handle messages from opener window here
            // console.log('Received message from opener:', event.data.token);
            localStorage.setItem("auth-tokens", JSON.stringify({
                "access_token": event.data.token,
                "expires_in": 3600, // 过期时间24小时
                "token_type": "Bearer"
            }));
            RED.init({
                apiRootUrl: ""
            });
        });
    } 
    else {
        RED.init({
            apiRootUrl: ""
        });
    }
    
    
    
});
